sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.page = 1;
    c.search = '';
    c.totalPaginas = 1;

    c.buscar = function() {
        c.irPara(1);
    };

    c.irPara = function(pagina) {
        c.page = pagina;
        c.data.action = 'listar';
        c.data.page = pagina;
        c.data.search = c.search;
        c.server.update().then(function(r) {
            c.totalPaginas = Math.max(1, Math.ceil(r.data.total / r.data.limit));
        });
    };

    c.irPara(1);
};

sp_widget.script:
(function() {
    data.clientes = [];
    data.total = 0;
    data.limit = 20;

    var page = parseInt(input && input.page || 1, 10);
    var search = (input && input.search) || '';
    var limit = data.limit;
    var offset = (page - 1) * limit;

    var gr = new GlideRecord('x_espaco_cliente');
    if (search) {
        gr.addQuery('nome', 'CONTAINS', search).addOrCondition('email', 'CONTAINS', search);
    }
    gr.orderBy('nome');
    gr.chooseWindow(offset, offset + limit);
    gr.query();
    while (gr.next()) {
        data.clientes.push({
            sys_id: gr.getUniqueValue(),
            nome: gr.getValue('nome'),
            email: gr.getValue('email'),
            telefone: gr.getValue('telefone'),
            consentimento_lgpd: gr.getValue('consentimento_lgpd') == 'true'
        });
    }

    var count = new GlideAggregate('x_espaco_cliente');
    if (search) {
        count.addQuery('nome', 'CONTAINS', search).addOrCondition('email', 'CONTAINS', search);
    }
    count.addAggregate('COUNT');
    count.query();
    data.total = count.next() ? parseInt(count.getAggregate('COUNT'), 10) : 0;
})();
